(function(){

const findNodeById = (layer, targetId) => {

  if (!layer) {
    return null;
  }


  if (layer.title === targetId) {
    return layer;
  }


  if (layer.sublayers != undefined && layer.sublayers.items.length > 0) {
    for (const child of layer.sublayers.items) {
      const found = findNodeById(child, targetId);
      if (found) {
        return found; 
      }
    }
  } else if (layer.layers != undefined && layer.layers.items.length > 0) {
    for (const child of layer.layers.items) {
      const found1 = findNodeById(child, targetId);
      if (found1) {
        return found1; 
      }
    }
  }
  return undefined;
}


  for (const lyr of $mapInfo.map.map.allLayers.items) {
       const l = findNodeById(lyr,$layerId.result);
       if(l != undefined) {
         return l;
       }
  }


})()
